
.opening {
  max-width: 640px;
  margin: 6px auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 14px;
  padding: 14px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
}

.head {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
}

.creator-note {
  flex: 1;
  font-size: 13px;
  color: var(--c-text);
  background: var(--c-panel);
  border-left: 3px solid var(--c-primary);
  border-radius: 6px;
  padding: 8px 10px;
}

.creator-note small {
  color: var(--c-muted);
}

.field {
  margin-bottom: 12px;
}

.field > label {
  display: block;
  font-size: 13px;
  font-weight: 800;
  color: var(--c-primary);
  margin-bottom: 6px;
  letter-spacing: 0.04em;
}

.opts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.opts.col {
  flex-direction: column;
}

.opts button {
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text);
  border-radius: 8px;
  padding: 8px 12px;
  cursor: pointer;
  text-align: left;
}

.opts button small {
  display: block;
  color: var(--c-muted);
  font-size: 11px;
}

.opts button .mv-chip {
  margin-left: 5px;
  font-size: 11px;
}

.opts button.on {
  background: var(--c-primary);
  border-color: var(--c-primary);
  color: #1b1712;
}

.opts button.on small,
.opts button.on .mv-chip {
  color: rgba(27, 23, 18, 0.72);
}

.opts button small.cost {
  color: var(--c-danger);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 8px;
}

.input {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.input.wide {
  grid-column: 1 / -1;
}

.input > span {
  font-size: 12px;
  color: var(--c-muted);
}

.input input,
.input textarea {
  background: var(--c-panel);
  border: 1px solid var(--c-border);
  border-radius: 7px;
  color: var(--c-text);
  padding: 7px 9px;
  font-family: inherit;
  font-size: 13px;
  outline: none;
}

.input input:focus,
.input textarea:focus {
  border-color: var(--c-primary);
}

.submit {
  width: 100%;
  background: var(--c-primary);
  color: #1b1712;
  border: none;
  border-radius: 9px;
  padding: 12px;
  font-size: 15px;
  font-weight: 800;
  cursor: pointer;
  letter-spacing: 0.08em;
}

.submit:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.done-tip {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--c-muted);
  text-align: center;
}

.loading {
  padding: 14px;
  text-align: center;
  color: var(--c-muted);
}
